/* Une horloge de jeu explicite. Le temps réel ne change jamais les probabilités. */
let clockRunning=false,clockLast=0,clockWantResume=false,spinTimer=null,spinContext=null,lastClockSave=0;
const CLOCK_YEAR_SECONDS=24;
const monthNames=['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'];
const timeBaseWelcome=welcome,timeBaseLife=lifeView,timeBaseSources=sources,timeBaseDecide=decide,timeBaseAct=act;
const timeBaseNav=nav;
function calendarLabel(){const month=Math.min(11,Math.floor((state.clock?.fraction||0)*12));return monthNames[month]+' '+state.year}
function timelineHUD(){if(!state)return'';const p=state.person,f=state.clock?.fraction||0,born=state.year-p.age;return`<section class="time-console" aria-label="Chronologie et vitesse du jeu"><div class="time-top"><div class="live-date"><span class="clock-dot ${clockRunning?'running':''}"></span><div><div class="eyebrow" id="clock-status">${p.alive?state.pending?'Une décision vous attend':clockRunning?'Le temps s’écoule':'Le temps est en pause':'Cette vie est achevée'}</div><strong id="clock-date">${calendarLabel()}</strong><small id="clock-age">${p.age} ans · ${Math.floor(f*12)} mois</small></div></div><div class="clock-controls"><button class="play-button" id="clock-play" aria-label="${clockRunning?'Mettre en pause':'Lancer le temps'}" onclick="toggleClock()" ${!p.alive?'disabled':''}>${clockRunning?'Ⅱ':'▶'}</button><div class="speed-group" aria-label="Vitesse du temps">${[1,2,4].map(n=>`<button class="${state.clock.speed===n?'active':''}" aria-label="Vitesse fois ${n}" aria-pressed="${state.clock.speed===n}" onclick="setSpeed(${n})">×${n}</button>`).join('')}</div><button class="year-step" title="Passer à l’année suivante" onclick="advance()" ${!p.alive||state.pending?'disabled':''}>+1 an →</button></div></div><div class="year-viewport"><div class="year-rail">${Array.from({length:11},(_,i)=>{const year=state.year+i-4,age=year-born;return`<div class="year-tick ${i===4?'now':''} ${i<4?'past':''}"><b>${year}</b><i></i><small>${age<0?'Avant votre naissance':age+' ans'}</small></div>`}).join('')}<div class="year-playhead" id="year-playhead" style="left:${(4+f)/11*100}%"><span></span></div></div></div><div class="time-bottom"><span id="clock-note">${clockRunning?'Les petites histoires apparaissent au fil des mois.':'Les décisions importantes mettent le jeu en pause.'}</span><span><b id="speed-description">${CLOCK_YEAR_SECONDS/state.clock.speed} s</b> par année &nbsp; · &nbsp; <button onclick="clockGuide()">Comment le temps fonctionne ↗</button></span></div></section>`}
function updateClockUI(){if(!state)return;const p=state.person,f=state.clock.fraction;const set=(id,text)=>{const n=document.getElementById(id);if(n)n.textContent=text};set('clock-date',calendarLabel());set('clock-age',p.age+' ans · '+Math.floor(f*12)+' mois');set('clock-status',!p.alive?'Cette vie est achevée':state.pending?'Une décision vous attend':clockRunning?'Le temps s’écoule':'Le temps est en pause');set('clock-play',clockRunning?'Ⅱ':'▶');set('life-play',clockRunning?'Mettre en pause Ⅱ':'Laisser la vie avancer ▶');const play=document.getElementById('clock-play');if(play)play.setAttribute('aria-label',clockRunning?'Mettre en pause':'Lancer le temps');const head=document.getElementById('year-playhead');if(head)head.style.left=(4+f)/11*100+'%';set('clock-note',clockRunning?'Les petites histoires apparaissent au fil des mois.':'Les décisions importantes mettent le jeu en pause.');const dot=document.querySelector('.clock-dot');if(dot)dot.classList.toggle('running',clockRunning)}
function pauseClock(){clockRunning=false;clockLast=0;updateClockUI()}
function toggleClock(){if(!state||!state.person.alive)return;if(clockRunning){pauseClock();clockWantResume=false;save();return}if(state.pending){toast('Un tournant de vie attend votre décision.');nav('life');return}if($('#modal').open){toast('Fermez le panneau ouvert avant de relancer le temps.');return}clockRunning=true;clockLast=performance.now();clockWantResume=false;Life.yearMoments(state);updateClockUI()}
function setSpeed(n){if(!state||![1,2,4].includes(n))return;state.clock.speed=n;clockLast=performance.now();save();render()}
function stepYear(auto=false){if(!state||state.pending||!state.person.alive)return false;if(!Life.year(state))return false;if(state.pending||!state.person.alive){clockWantResume=auto&&state.person.alive;pauseClock()}save();render();if(!state.person.alive)toast('Cette vie est terminée. Vous pouvez découvrir ce qui continue dans votre lignée.');return true}
function advance(){if(state?.pending){toast('Répondez au chapitre en cours avant de laisser passer une année.');return}pauseClock();clockWantResume=false;stepYear(false)}
function clockTick(now){if(!state||!clockRunning){clockLast=now;return}if(state.pending||!state.person.alive||$('#modal').open){pauseClock();return}if(!clockLast){clockLast=now;return}const elapsed=Math.min(500,Math.max(0,now-clockLast));clockLast=now;state.clock.fraction+=elapsed/1000/CLOCK_YEAR_SECONDS*state.clock.speed;const moments=Life.yearMoments(state);let changed=false;for(const m of moments.items){if(state.clock.fraction*12>=m.month&&Life.moment(state,m.id))changed=true}if(state.clock.fraction>=1-1e-9){state.clock.fraction=.9999;stepYear(true)}else if(changed){save();render()}else updateClockUI();if(now-lastClockSave>1500){save();lastClockSave=now}}
function clockGuide(){pauseClock();modal(`<h2>Chaque année, chaque petite histoire.</h2><p>À ×1, une année dure ${CLOCK_YEAR_SECONDS} secondes ; à ×2, ${CLOCK_YEAR_SECONDS/2} secondes ; à ×4, ${CLOCK_YEAR_SECONDS/4} secondes. Le curseur représente le mois de l’année en cours.</p><p>Deux instants de vie apparaissent chaque année. Certains ne font que raconter votre quotidien ; d’autres font légèrement évoluer votre humeur ou vos compétences. Les grands tournants, les décisions de projet et les urgences vous arrêtent pour choisir.</p><p>Changer de vitesse ne modifie pas les probabilités. Le temps ne progresse pas lorsque cet onglet est masqué. Vous pouvez mettre en pause à tout moment pour gérer votre vie.</p><button class="btn primary" onclick="document.getElementById('modal').close()">Revenir à ma vie</button>`)}
// Function expressions intentionally preserve the already-installed UI implementations.
welcome=function(){timeBaseWelcome();const app=$('#app');app.innerHTML=app.innerHTML.replace('Lignées 2.0 · Le temps, le risque, la transmission','197 pays · Des années qui défilent · Des générations qui continuent').replace('Commencer une vie &nbsp; →','Faire tourner le destin &nbsp; ↻').replace('Naissance pondérée par des parts approximatives des naissances mondiales.','197 pays nommés, sans catégorie « autres ». Naissance pondérée par des volumes approximatifs.').replace('8 secteurs professionnels, 12 parcours de projets et des générations autonomes.','Une frise qui avance. Des événements au fil des mois. Pause et vitesses ×1, ×2, ×4.');app.innerHTML=app.innerHTML.replace('<label for="country">Votre naissance</label>','<label for="country">Votre naissance <button class="inline-link" onclick="countryAtlas()">Explorer les 197 pays ↗</button></label>')};
nav=function(id){timeBaseNav(id);updateClockUI()};
lifeView=function(){let html=timeBaseLife();html=html.replace('Vivre la prochaine année →','Année suivante →').replace('Clore cette année →','Année suivante →');if(state?.moments){const latest=state.journal.filter(x=>x.kind==='instant'&&x.person===state.person.id&&x.year===state.year).slice(-1)[0];if(latest)html=html.replace('<div class="layout">',`<div class="moment-card"><span class="eyebrow">${monthNames[Math.max(0,(latest.month||1)-1)]} ${latest.year} · Un instant de vie</span><p>${esc(latest.text)}</p></div><div class="layout">`)}return html};
decide=function(i){const wasBirth=state.pending?.id==='birth';const chosen=state.pending?.choices[i];if(!chosen)return;const isRoll=!!chosen.fx.roll;const before=state.person.riskLog.length;if(!Life.choose(state,i)){toast(state.lastError||'Ce choix n’est plus accessible.');return}save();render();if(isRoll&&state.person.riskLog.length>before){const r=state.person.riskLog.at(-1);presentRisk(r,()=>{if(clockWantResume&&!state.pending){clockWantResume=false;clockRunning=true;clockLast=performance.now();updateClockUI()}})}else if((clockWantResume||wasBirth)&&!state.pending&&state.person.alive){clockWantResume=false;clockRunning=true;clockLast=performance.now();Life.yearMoments(state);updateClockUI()}};
act=function(type,value){if(!state)return;const before=state.person.riskLog.length;const wasRunning=clockRunning;pauseClock();const result=Life.action(state,type,value);if(result.ok){save();render();if(state.person.riskLog.length>before&&['applyJob','promotion','date','child','scholarship'].includes(type)){presentRisk(state.person.riskLog.at(-1));return}}toast(result.message||'Action indisponible.');if(wasRunning)updateClockUI()};
function start(){pauseClock();const code=$('#country').value,year=Number($('#birthyear').value),seed=$('#seed').value.trim()||crypto.getRandomValues(new Uint32Array(1))[0].toString(36).toUpperCase();state=Life.create(seed,code,year);state.initial={code,year};page='life';save();revealBirth()}
function revealBirth(){const p=state.person,b=p.birth,c=Life.country(state);pauseClock();clearInterval(spinTimer);spinContext={type:'birth',stage:0,frame:0,started:performance.now()};const chosen=state.initial?.code!=='random';modal(`<div class="birth-heading"><div class="eyebrow">Une vie parmi des milliards</div><h2>Le hasard écrit votre première ligne.</h2><p>Trois tirages. Un point de départ. Aucune vie ne ressemble tout à fait à une autre.</p></div><div class="birth-orbit"><span>✧</span><i></i><b>↻</b></div><div class="birth-slots"><div class="birth-slot" id="birth-slot-0"><div class="eyebrow">01 · Le lieu</div><strong id="birth-value-0">${chosen?esc(c.name):'Le monde tourne…'}</strong><small id="birth-prob-0">${chosen?'Scénario choisi':'Pondéré par les naissances'}</small></div><div class="birth-slot" id="birth-slot-1"><div class="eyebrow">02 · Le sexe à la naissance</div><strong id="birth-value-1">À découvrir</strong><small id="birth-prob-1">Tirage suivant</small></div><div class="birth-slot" id="birth-slot-2"><div class="eyebrow">03 · Le foyer</div><strong id="birth-value-2">À découvrir</strong><small id="birth-prob-2">Tirage suivant</small></div></div><div id="birth-result" class="birth-result hidden"></div><button id="birth-skip" class="btn" style="width:100%;margin-top:20px" onclick="finishBirth()">Révéler les tirages maintenant</button><div class="hint" style="text-align:center">Le résultat est fixé par la seed. L’animation ne relance jamais le tirage.</div>`);$('#modal').classList.add('birth-modal');const reduce=typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduce){finishBirth();return}if(chosen){settleBirth(0);spinContext.stage=1}spinTimer=setInterval(()=>{if(!spinContext||spinContext.type!=='birth')return;const n=spinContext.stage,elapsed=performance.now()-spinContext.started;const pools=[Life.countries.filter(x=>x.births>0).map(x=>x.name),['Fille','Garçon'],['Très modeste','Modeste','Intermédiaire','Aisée','Très aisée']];const node=document.getElementById('birth-value-'+n);if(node)node.textContent=pools[n][Math.floor(Life.hash(state.seed+'|animation|'+n+'|'+spinContext.frame++)*pools[n].length)];const slot=document.getElementById('birth-slot-'+n);if(slot)slot.classList.add('rolling');if(elapsed>1400){settleBirth(n);spinContext.stage++;spinContext.started=performance.now();if(spinContext.stage>2)finishBirth()}},90)}
function settleBirth(n){const b=state.person.birth,chosen=state.initial?.code!=='random';const labels=[b.countryName,b.sex==='M'?'Garçon':'Fille',b.familyTier],notes=[chosen?'Lieu choisi pour ce scénario':(b.countryShare*100).toFixed(b.countryShare<.001?4:2)+' % des naissances du modèle',(b.sexProbability*100).toFixed(1)+' % · ratio de référence', 'Quintile local · 20 % dans le modèle'];const value=document.getElementById('birth-value-'+n),prob=document.getElementById('birth-prob-'+n),slot=document.getElementById('birth-slot-'+n);if(value)value.textContent=labels[n];if(prob)prob.textContent=notes[n];if(slot){slot.classList.remove('rolling');slot.classList.add('settled')}}
function finishBirth(){if(!state||!spinContext||spinContext.type!=='birth')return;clearInterval(spinTimer);spinTimer=null;[0,1,2].forEach(settleBirth);const p=state.person,b=p.birth;const node=document.getElementById('birth-result');if(node){node.classList.remove('hidden');node.innerHTML=`<h3>Vous êtes ${esc(p.name)} ${esc(p.surname)}.</h3><p>${esc(b.structure)} · ${b.siblings} frère${b.siblings>1?'s':''} ou sœur${b.siblings>1?'s':''} au départ · ${b.urban?'milieu urbain':'milieu rural'}.<br>Ressources du foyer : ${money(b.income)} par an.</p><button class="btn primary" onclick="enterLife()">Incarner cette vie →</button>`}const skip=document.getElementById('birth-skip');if(skip)skip.style.display='none';spinContext.stage=3;save()}
function enterLife(){page='life';clearInterval(spinTimer);spinContext=null;state.birthRevealed=true;$('#modal').classList.remove('birth-modal');$('#modal').close();save();render();window.scrollTo(0,0)}
function presentRisk(record,done){pauseClock();clearInterval(spinTimer);spinContext={type:'risk',record,done,revealed:false};const pct=percent(record.prob);modal(`<div class="eyebrow">Le résultat n’est jamais acquis</div><h2 style="margin-top:12px">${esc(record.title)}</h2><p>Chance estimée avant le tirage : <b style="color:var(--green)">${pct}</b>.</p><div class="risk-wheel-wrap"><div class="wheel-pointer">▼</div><div class="risk-wheel spinning" id="risk-wheel" style="--chance:${record.prob*360}deg"><div><strong>${pct}</strong><small>de chance</small></div></div></div><div id="risk-outcome" class="risk-outcome"><span class="eyebrow">La roue tourne…</span></div><button class="btn" id="risk-reveal" style="width:100%;margin-top:15px" onclick="finishRisk()">Voir l’issue</button><div class="hint">La roue illustre un tirage unique enregistré dans votre partie. La vitesse et l’animation ne modifient pas ses chances.</div>`);const reduced=typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches;spinTimer=setTimeout(finishRisk,reduced?0:1800)}
function finishRisk(){if(!spinContext||spinContext.type!=='risk'||spinContext.revealed)return;clearTimeout(spinTimer);spinContext.revealed=true;const r=spinContext.record,w=document.getElementById('risk-wheel');if(w){w.classList.remove('spinning');const point=r.result?Math.max(2,r.prob*180):r.prob*360+(360-r.prob*360)*.5;w.style.transform='rotate('+(-point)+'deg)'}const out=document.getElementById('risk-outcome');if(out){out.classList.add(r.result?'success':'failure');out.innerHTML=`<strong>${r.result?'Le pari vous sourit.':'Cette fois, le résultat est défavorable.'}</strong><p>${esc(state.journal.at(-1)?.text||'La vie continue.')}</p>`}const b=document.getElementById('risk-reveal');if(b){b.textContent='Poursuivre mon histoire →';b.className='btn primary';b.setAttribute('onclick','closeRisk()')}}
function closeRisk(){const cb=spinContext?.done;spinContext=null;$('#modal').close();render();if(cb)cb()}
function countryAtlas(){pauseClock();modal(`<h2>197 pays. Aucune case « autres ».</h2><p>Le tirage utilise les naissances approximatives de chaque pays, pas un poids identique. Les micro-États restent présents. Vous pouvez aussi choisir un pays pour explorer ce scénario.</p><label for="country-search">Chercher un pays</label><input id="country-search" placeholder="France, Inde, Brésil…" oninput="filterAtlas(this.value)"><div class="atlas-list" id="atlas-list">${atlasRows('')}</div><p class="hint">Population et natalité arrondies, référence 2024. Profils économiques et de santé complétés par des estimations de simulation. Le Vatican est présent comme scénario choisi ; le modèle ne lui attribue aucune naissance.</p>`)}
function atlasRows(q){return Life.countries.filter(c=>c.name.toLocaleLowerCase('fr').includes(q.toLocaleLowerCase('fr'))).map(c=>`<button class="atlas-row" onclick="selectBirthCountry('${c.code}')"><span>${esc(c.name)}<small>${c.region}${Life.currency?' · revenu moyen ≈ '+Math.round(Life.currency.countryIncome(null,c).eur).toLocaleString('fr-FR')+' €/an':''}</small></span><b>${(c.births/Life.worldDataset.totalBirths*100).toFixed(c.births/Life.worldDataset.totalBirths<.001?4:2)} %</b></button>`).join('')||'<p>Aucun pays ne correspond.</p>'}
function filterAtlas(q){const n=document.getElementById('atlas-list');if(n)n.innerHTML=atlasRows(q)}
function selectBirthCountry(code){if(state){toast('Le pays de naissance d’une vie commencée est déjà fixé. Une migration se prépare dans Projets.');return}$('#modal').close();const n=$('#country');if(n)n.value=code;toast('Pays sélectionné pour votre prochaine naissance.')}
sources=function(){timeBaseSources();const d=$('#modal');d.innerHTML=d.innerHTML.replace('24 profils nationaux et un groupe « autres pays ».','197 pays explicitement nommés, dont les micro-États.').replace('Les poids représentent des volumes annuels de naissances approximatifs, normalisés par le moteur.','Les poids sont calculés à partir de populations arrondies et de taux de natalité arrondis (référence 2024), puis normalisés sur les 197 pays inclus. Les territoires dépendants ne constituent pas des entrées distinctes.').replace('Les données complètes ne sont pas encore intégrées à cette version.','La couverture géographique est complète pour cette liste ; la précision des profils reste limitée.');d.innerHTML+='<p><b>Sexe à la naissance :</b> ratio de référence de 105 garçons pour 100 filles, appliqué uniformément, soit environ 51,2 % / 48,8 %. Ce n’est pas une mesure spécifique à chaque pays et cela ne préjuge pas de l’identité de genre.</p><p><b>Foyer :</b> le quintile local est tiré à 20 % par tranche dans le modèle. Structure familiale, fratrie et urbanité restent des hypothèses de gameplay.</p><a href="https://www.ined.fr/en/everything_about_population/demographic-facts-sheets/faq/is-it-true-that-as-many-girls-as-boys-are-born-on-earth" target="_blank" rel="noopener">INED · ratio des sexes à la naissance ↗</a>';};
function renderTimelineEntries(entries){return`<div class="timeline">${entries.map(x=>`<div class="entry ${x.important?'important':''}"><time>${x.month?monthNames[x.month-1]+' ':''}${x.year} &nbsp; · &nbsp; ${x.age} ans${x.kind==='instant'?' · instant de vie':''}</time><p>${esc(x.text)}</p></div>`).join('')||'<div class="empty">Les premières pages restent à écrire.</div>'}</div>`}
timeline=renderTimelineEntries;
if(typeof document.addEventListener==='function'){document.addEventListener('visibilitychange',()=>{if(document.hidden){pauseClock();if(state)save()}});document.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','SELECT','TEXTAREA','BUTTON'].includes(e.target.tagName)&&!$('#modal').open){e.preventDefault();toggleClock()}})}
$('#modal').addEventListener('close',()=>{if(spinContext?.type==='birth'){clearInterval(spinTimer);spinContext=null;state.birthRevealed=true;$('#modal').classList.remove('birth-modal');save();render()}else if(spinContext?.type==='risk'){clearTimeout(spinTimer);spinContext=null;render()}});
if(state){Life.ensure(state);state.clock.fraction=state.clock.fraction||0;Life.yearMoments(state);save()}render();
setInterval(()=>clockTick(performance.now()),100);
